export function lbRefusedFrame(serverAddress, record, request) {
  return `LB ${serverAddress} -> ${record.to} | ${request} => connection refused (nothing enqueued)`;
}

// R1a: the LB hop itself, one implementation for both trace machines
// (trace.js stages 2-5 and trace-stage6.js's chain). The branch text moved
// byte-shape-identical from trace.js's stage-5 LB branch; the stage-6
// machine previously re-implemented it without the refusal branch and skip
// narration, narrating an all-down record as "[object Object]" and then
// walking a phantom chain (finding 1-01).
//
// DOCUMENTS: the LB-hop story parity contract — one refused field, one
// frame pair, one skip narration across the machines. The trace mutates in
// place (refused/targetServer) and the hop's frame is returned; no engine
// closures are captured (same seam discipline as the helpers above).
// CHECKS: an all-down pool aborts with the refusal card — trace.refused
// flips true, onRefusal fires, no targetServer is set, so the walk ends at
// the LB hop; a one-down pool narrates the crossed seat (lastSkip) without
// aborting the served story (no refused flip); a healthy pool keeps the
// clean byte shape "LB ... queued" with no skip suffix.
export function lbEnqueueHop(trace, { serverAddress, lb, bumpTick, onRefusal }) {
  const atTick = bumpTick();
  const target = lb.enqueue({
    id: `you:${atTick}`,
    from: trace.from,
    to: serverAddress,
    request: trace.request,
    atTick,
    isYou: true,
  });
  if (target?.refused === true) {
    trace.refused = true;
    onRefusal?.(target);
    return { frame: lbRefusedFrame(serverAddress, target, trace.request), refused: true };
  }
  trace.targetServer = target;
  return {
    frame: lbEnqueuedFrame(serverAddress, target, trace.request, lb.lastSkip?.()),
    refused: false,
  };
}

